        events, ports, link_ids, lags, config
    )
    if max_work is not None:
        # 与 reload 入口同一公式：独立链路副本与空状态，不改动既有数据
        reload_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            reload_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security(
        bridges,
        links,
        delay,
        bridge,
